sample.code:
#include <iostream>
using namespace std;

int main() {
    int i = 1;
    while (i <= 5) {
        cout << i << endl;
        i++;
    }
    cout << "Done" << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int marks, total = 0, count = 0;
    cin >> marks;
    while (marks != -1) {
        total += marks;
        count++;
        cin >> marks;
    }
    if (count > 0) {
        cout << "Average = " << (double) total / count << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int num, sum = 0;
    cin >> num;
    while (num > 0) {
        sum += num % 10;
        num /= 10;
    }
    cout << "Sum of digits = " << sum << endl;
    return 0;
}

